-- 3. 航班组员编制
-- ============================================================

SELECT f.id, v.division, v.acting_rank, v.plan_value
FROM flight f
CROSS JOIN (VALUES ('P','CA',1),('P','FO',1),('C','PU',1),('C','FA',3)) AS v(division, acting_rank, plan_value)
WHERE f.fleet IN ('A321','B737') AND f.flt_dt BETWEEN '2026-03-01' AND '2026-03-31'
  AND NOT EXISTS (SELECT 1 FROM flight_composition fc WHERE fc.flt_id = f.id AND fc.division = v.division AND fc.acting_rank = v.acting_rank)
ON CONFLICT DO NOTHING;

SELECT f.id, v.division, v.acting_rank, v.plan_value
FROM flight f
CROSS JOIN (VALUES ('P','CA',2),('P','FO',2),('C','PU',2),('C','FA',6)) AS v(division, acting_rank, plan_value)
WHERE f.fleet IN ('B787','A330') AND f.flt_dt BETWEEN '2026-03-01' AND '2026-03-31'
  AND NOT EXISTS (SELECT 1 FROM flight_composition fc WHERE fc.flt_id = f.id AND fc.division = v.division AND fc.acting_rank = v.acting_rank)
ON CONFLICT DO NOTHING;

